   123|
   124|async function handleSendOtp(req: Request, payload: Record<string, unknown>) {
   125|  const phone = norm((payload.phone as string) || "");
   126|  if (!phone || phone.length < 10) {
   127|    return new Response(JSON.stringify({ error: "Valid phone number required" }), {
   128|      status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
   129|    });
   130|  }
   131|
   132|  let sid = Deno.env.get("TWILIO_ACCOUNT_SID") || "";
   133|  let tok = Deno.env.get("TWILIO_AUTH_TOKEN") || "";
   134|  if (!sid || !tok) {
   135|    return new Response(JSON.stringify({ error: "SMS provider not configured" }), {
   136|      status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
   137|    });
   138|  }
   139|
   140|  const otp = (payload.otp as string) || generateOtp();
   141|  const salt = crypto.randomUUID();
   142|  const hash = await sha256(`${phone}:${otp}:${salt}`);
   143|
   144|  const { error: dbErr } = await adminClient().from("phone_otps").insert({
   145|    phone, otp_hash: hash, salt,
   146|    expires_at: new Date(Date.now() + 5 * 60 * 1000).toISOString(),
   147|  });
   148|  if (dbErr) {
   149|    console.error("OTP store error:", dbErr);
   150|    return new Response(JSON.stringify({ error: "Failed to generate OTP" }), {
   151|      status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
   152|    });
   153|  }
   154|
   155|  const res = await sendTwilioSms(phone, `Your VitaHero verification code is: ${otp}`, sid, tok);
   156|  if (!res.ok) {
   157|    return new Response(JSON.stringify({ error: res.error }), {
   158|      status: 502, headers: { ...corsHeaders, "Content-Type": "application/json" },
   159|    });
   160|  }
   161|
   162|  return new Response(JSON.stringify({ success: true, expiresIn: 300 }), {
   163|    headers: { ...corsHeaders, "Content-Type": "application/json" },
   164|  });
   165|}
