   175|    });
   176|  }
   177|
   178|  const admin = adminClient();
   179|
   180|  // Look up unverified, non-expired OTPs
   181|  const { data: records, error: lookErr } = await admin
   182|    .from("phone_otps")
   183|    .select("*")
   184|    .eq("phone", phone)
   185|    .eq("verified", false)
   186|    .gt("expires_at", new Date().toISOString())
   187|    .order("created_at", { ascending: false })
   188|    .limit(5);
