package com.rork.vitahero.data

import com.rork.vitahero.Config
import io.ktor.client.call.body
import io.ktor.client.request.header
import io.ktor.client.request.post
import io.ktor.client.request.setBody
import io.ktor.client.statement.bodyAsText
import io.ktor.http.ContentType
import io.ktor.http.contentType
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.buildJsonArray
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.jsonPrimitive
import kotlinx.serialization.json.put
import kotlinx.serialization.json.putJsonObject

/**
 * AI Diet Coach — calls the Rork AI proxy (Vercel AI Gateway) to generate
 * personalised paediatric diet tips based on the child's age, BMI, nutrition
 * flags, and meal history.
 *
 * Uses openai/gpt-4.1-nano — cost-effective, fast, supports tool use and
 * reasoning. All requests are proxied through Rork Toolkit for billing,
 * rate limiting, and cost tracking.
 */
object AIService {

    private val toolkitUrl get() = Config.EXPO_PUBLIC_TOOLKIT_URL
    private val toolkitKey get() = Config.EXPO_PUBLIC_RORK_TOOLKIT_SECRET_KEY
    private const val MODEL = "openai/gpt-4.1-nano"

    private val json = Json { ignoreUnknownKeys = true; isLenient = true }

    /**
     * Generate a personalised diet coaching tip for a kid.
     *
     * @param kid the child to generate tips for
     * @param meals the child's current meal plan
     * @param streak the child's meal-logging streak
     * @return AIDietContent with greeting, insight, suggestion, fun fact, and generated timestamp
     */
    suspend fun generateDietTip(
        kid: Kid,
        meals: List<MealItem>,
        streak: StreakInfo
    ): AIDietContent = withContext(Dispatchers.IO) {
        val eatenCount = meals.count { it.eaten }
        val totalKcal = meals.filter { it.eaten }.sumOf { it.kcal }
        val mealNames = meals.joinToString(", ") { "${it.name} (${it.kcal} kcal, ${if (it.eaten) "eaten" else "pending"})" }

        val systemPrompt = buildString {
            appendLine("You are a pediatric nutrition coach for VitaHero, an Indian child health app.")
            appendLine("You give culturally relevant, actionable diet tips for Indian parents.")
            appendLine("Focus on Indian foods: dal, roti, rice, sabzi, idli, dosa, poha, paneer, ragi, curd, sprouts, khichdi, etc.")
            appendLine("Respond ONLY with a valid JSON object containing exactly these 4 string fields:")
            appendLine("\"greeting\" — a warm 1-sentence greeting addressing the parent about the child by name")
            appendLine("\"insight\" — 1-2 sentences of nutritional insight specific to the child's age/health data")
            appendLine("\"suggestion\" — 1 specific, actionable meal suggestion using Indian ingredients")
            appendLine("\"funFact\" — 1 interesting nutrition fact relevant to Indian diet")
            appendLine("Keep each field concise (1-2 sentences max). No markdown, no extra text.")
        }

        val userPrompt = buildString {
            appendLine("Child: ${kid.name}, ${kid.age} years old, ${kid.gender}")
            appendLine("Height: ${kid.heightCm.toInt()} cm, Weight: ${kid.weightKg.toInt()} kg, BMI: %.1f".format(kid.bmi))
            appendLine("Health Score: ${kid.overallScore}/100")
            appendLine("Dental: ${kid.dental.name}, Eyesight: ${kid.eyesight.name}, Nutrition: ${kid.nutrition.name}")
            appendLine("Today's meals ($eatenCount/${meals.size} eaten, $totalKcal kcal): $mealNames")
            appendLine("Current streak: ${streak.currentStreak} days, Best streak: ${streak.bestStreak} days")
            if (kid.nutrition == HealthFlag.WATCH) appendLine("Nutrition needs attention — focus on iron-rich and protein-rich Indian foods.")
            if (kid.bmi < 14f) appendLine("BMI is on the lower side — suggest calorie-dense, nutritious Indian foods.")
            if (kid.bmi > 19.5f) appendLine("BMI is on the higher side — suggest lighter, fibre-rich Indian options.")
            appendLine("Generate a personalised, culturally-appropriate Indian diet coaching tip.")
        }

        try {
            val http = SupabaseService.http
            val body = buildJsonObject {
                put("model", MODEL)
                putJsonArray("messages") {
                    add(buildJsonObject {
                        put("role", "system")
                        put("content", systemPrompt)
                    })
                    add(buildJsonObject {
                        put("role", "user")
                        put("content", userPrompt)
                    })
                }
                put("temperature", 0.7)
                put("max_tokens", 400)
            }

            val resp = http.post("$toolkitUrl/v2/vercel/v1/chat/completions") {
                header("Authorization", "Bearer $toolkitKey")
                contentType(ContentType.Application.Json)
                setBody(body.toString())
            }

            val text = resp.bodyAsText()
            val parsed = json.decodeFromString<ChatCompletionResponse>(text)
            val content = parsed.choices.firstOrNull()?.message?.content ?: ""

            // Parse the JSON from the AI response
            val aiJson = try {
                json.decodeFromString<AIDietJson>(content.trim())
            } catch (_: Exception) {
                // Fallback: try to extract JSON from markdown code block
                val jsonBlock = content
                    .substringAfter("```json", "")
                    .substringBefore("```", "")
                    .ifBlank { content.substringAfter("```", "").substringBefore("```") }
                    .trim()
                try {
                    json.decodeFromString<AIDietJson>(jsonBlock)
                } catch (_: Exception) {
                    fallbackTip(kid, streak)
                }
            }

            AIDietContent(
                greeting = aiJson.greeting,
                insight = aiJson.insight,
                suggestion = aiJson.suggestion,
                funFact = aiJson.funFact,
                generatedAt = "AI-generated for ${kid.name}",
                isGenerating = false,
            )
        } catch (e: Exception) {
            // Silent fallback to local generation if AI is unavailable
            fallbackTip(kid, streak)
        }
    }

    private fun fallbackTip(kid: Kid, streak: StreakInfo): AIDietContent {
        val age = kid.age
        val name = kid.name
        val greeting = when {
            kid.nutrition == HealthFlag.GOOD -> "Great job, $name's eating well! \uD83E\uDD57"
            kid.nutrition == HealthFlag.WATCH -> "Let's boost $name's nutrition! \uD83D\uDCAA"
            else -> "$name needs some extra care with meals \u2764\uFE0F"
        }
        val insight = when {
            age <= 6 -> "Kids $age and under need calcium-rich foods for strong bones. Milk, curd, and ragi are excellent choices."
            age <= 10 -> "At age $age, $name needs plenty of protein for growth spurts. Eggs, dal, paneer, and sprouts build muscle."
            else -> "Growing teens like $name need iron-rich foods. Include green leafy veggies, dates, and jaggery daily."
        }
        val suggestion = when {
            kid.nutrition == HealthFlag.WATCH -> "Try adding a boiled egg or a bowl of sprout chaat to $name's evening snack."
            kid.bmi < 14f -> "Add a handful of nuts and a banana to $name's day. Healthy fats help catch up on the growth curve."
            kid.bmi > 19.5f -> "Swap packaged snacks with cucumber/carrot sticks and homemade roasted chana."
            else -> "Keep up the great balance! Rotate between dal-rice, khichdi, idli-sambar, and roti-sabzi for variety."
        }
        val funFact = listOf(
            "Soaking almonds overnight removes tannins and makes nutrients easier to absorb!",
            "Vitamin C from lemon on dal helps absorb iron 3x better. Squeeze away!",
            "Ragi (finger millet) has 10x more calcium than rice. Perfect for growing kids.",
            "Curd has probiotics that keep the gut healthy and boost immunity naturally.",
            "Jaggery has iron and minerals that refined sugar doesn't. Sweet and smart!"
        ).random()

        return AIDietContent(
            greeting = greeting, insight = insight,
            suggestion = suggestion, funFact = funFact,
            generatedAt = "Generated for $name", isGenerating = false,
        )
    }

    // ─── Response DTOs ────────────────────────────────────

    @Serializable
    data class ChatCompletionResponse(
        val choices: List<Choice> = emptyList()
    )

    @Serializable
    data class Choice(
        val message: Message = Message()
    )

    @Serializable
    data class Message(
        val content: String = ""
    )

    @Serializable
    data class AIDietJson(
        val greeting: String = "",
        val insight: String = "",
        val suggestion: String = "",
        val funFact: String = ""
    )
}

