 */
object LocaleStrings {

    private val en = mapOf(
        "notif_camp_title" to "Camp Coming Up!",
        "notif_camp_body" to "{camp} is in 2 days. Get the kids ready!",
        "notif_checkup_title" to "Upcoming Appointment",
        "notif_checkup_body" to "{kid} has a checkup with {doctor} today at {time}",
        "notif_diet_title" to "Log {kid}'s Meals",
        "notif_diet_body" to "Don't forget to mark today's meals for {kid}. Keep the streak going!",
    )

    private val hi = mapOf(
        "notif_camp_title" to "कैंप आने वाला है!",
        "notif_camp_body" to "{camp} 2 दिनों में है। बच्चों को तैयार करें!",
        "notif_checkup_title" to "आगामी अपॉइंटमेंट",
        "notif_checkup_body" to "{kid} की {doctor} के साथ आज {time} बजे चेकअप है",
        "notif_diet_title" to "{kid} का खाना लॉग करें",
        "notif_diet_body" to "{kid} के लिए आज का खाना मार्क करना न भूलें। स्ट्रीक जारी रखें!",
    )

    private val te = mapOf(
        "notif_camp_title" to "క్యాంపు రాబోతోంది!",
        "notif_camp_body" to "{camp} 2 రోజుల్లో ఉంది. పిల్లలను సిద్ధం చేయండి!",
        "notif_checkup_title" to "రాబోయే అపాయింట్‌మెంట్",
        "notif_checkup_body" to "{kid} కి {doctor} తో ఈరోజు {time} కి చెకప్ ఉంది",
        "notif_diet_title" to "{kid} భోజనాన్ని లాగ్ చేయండి",
        "notif_diet_body" to "{kid} కోసం ఈరోజు భోజనాన్ని గుర్తించడం మర్చిపోవద్దు. స్ట్రీక్ కొనసాగించండి!",
    )

    private val strings: Map<AppLocale, Map<String, String>> = mapOf(
        AppLocale.ENGLISH to en,
        AppLocale.HINDI to hi,
        AppLocale.TELUGU to te,
    )

    fun get(locale: AppLocale, key: String, fallback: String = ""): String {
        return strings[locale]?.get(key) ?: strings[AppLocale.ENGLISH]?.get(key) ?: fallback
    }
}

